SELECT c_comment, o_orderkey, n_name FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey WHERE n_name >= 'CANADA' AND o_orderstatus <> 'F' AND c_comment <> 'ing requests according to the stealthily express requests use among the furiously' AND c_name = 'Customer#000060165' ORDER BY n_name DESC, o_orderkey ASC
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '28-716-704-8686' AND s_name < 'Supplier#000001926' AND l_partkey > 34667 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000007016' order by sum(ps_partkey) DESC, min(s_name) ASC
SELECT o_shippriority, c_acctbal FROM orders, customer WHERE c_nationkey >= 24 AND c_name <> 'Customer#000149000' AND o_clerk > 'Clerk#000000781' AND c_comment = 'st slyly. carefully ironic asymptotes run according to the bl'
SELECT ps_availqty FROM partsupp WHERE ps_supplycost < 602.47 AND ps_partkey < 76637 AND ps_availqty = 7011 AND ps_suppkey <> 8879 ORDER BY ps_availqty DESC
select p_mfgr, ps_availqty, max(ps_comment) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty >= 9188 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by p_mfgr, ps_availqty having max(ps_comment) = 'ake furiously blithe requests. permanently ruthless accounts cajole along the boldly regular attainments. quickly regular'
select ps_availqty, p_mfgr, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 8735 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by p_mfgr, ps_availqty having min(p_container) = 'SM CAN'
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%burnished%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select s_comment, s_suppkey, l_extendedprice, max(s_name), sum(l_discount) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where l_commitdate = '1995-02-25' AND s_name < 'Supplier#000001926' AND l_partkey > 18720 group by l_extendedprice, s_suppkey, s_comment having sum(l_discount) <= 0.05 order by sum(l_discount) DESC, max(s_name) ASC
SELECT c_phone, o_orderstatus FROM customer, orders WHERE c_nationkey <> 10 AND o_totalprice = 28177.04 AND o_orderstatus >= 'P' AND o_orderpriority <> '3-MEDIUM' AND c_acctbal > 2379.26
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('TRUCK', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_suppkey FROM lineitem WHERE l_extendedprice > 27509.72 AND l_orderkey < 2753026 AND l_partkey <= 117322 AND l_commitdate >= '1994-06-27' ORDER BY l_suppkey DESC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 9  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('33', '18', '15', '24', '23', '32', '12')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('33', '18', '15', '24', '23', '32', '12')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_discount, o_orderkey, c_name, s_comment, n_comment, ps_availqty FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN customer ON c_nationkey = n_nationkey WHERE c_address = 'YBEHKrTMyR4CnpCFlg7SoRBji' AND l_linestatus > 'O'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#45'  and p_type not like 'STANDARD POLISHED%'  and p_size in (36, 7, 21, 23, 35, 44, 43, 34)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT o_orderdate, l_receiptdate FROM orders, lineitem WHERE o_shippriority >= 0 AND o_comment = 'ckages wake final accounts. carefully enticing asymptotes run quie' AND o_orderpriority <> '2-HIGH' AND l_linenumber < 1
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%almond%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
SELECT o_orderdate, l_receiptdate FROM lineitem JOIN orders ON o_orderkey = l_orderkey WHERE l_partkey <= 5867 AND l_shipinstruct <> 'DELIVER IN PERSON' AND l_orderkey > 2951751 AND l_commitdate >= '1996-01-02'
select l_commitdate, l_orderkey from lineitem, partsupp where l_suppkey < 164 AND l_orderkey < 56675 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select  o_year,  sum(case   when nation = 'JAPAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE PLATED STEEL'  ) as all_nations group by  o_year order by  o_year ;
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000122315' AND o_orderdate < '1995-01-28' AND o_comment = 'yly until the fluffily even requests. deposits a' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select  o_year,  sum(case   when nation = 'CANADA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL PLATED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#32'  and p_container = 'WRAP CAN'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select l_receiptdate, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 96753 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode >= 'AIR' AND p_retailprice = 1831.73
SELECT p_brand, l_comment, ps_partkey FROM part, partsupp, lineitem WHERE ps_supplycost <= 757.42 AND l_shipinstruct > 'TAKE BACK RETURN' AND ps_comment = 'ular dependencies above the accounts cajole final accounts. quickly unusual pinto beans haggle fluffily. blithe' AND l_partkey = 78908 ORDER BY l_comment ASC, ps_partkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 48  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT c_phone, o_shippriority FROM customer JOIN orders ON o_custkey = c_custkey WHERE c_phone <> '34-739-414-7239' AND c_address >= 'PYS6CkH6jZIPu2bMDwHTTcMJLPBGV9sK' AND c_acctbal > 5899.31 AND o_orderdate = '1996-06-10'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#52'  and p_type not like 'PROMO BURNISHED%'  and p_size in (44, 6, 21, 32, 50, 1, 39, 23)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT s_nationkey, ps_comment, COUNT(ps_suppkey), COUNT(s_acctbal) FROM supplier, partsupp WHERE ps_supplycost <> 315.24 AND ps_availqty = 2301 AND s_suppkey > 9223 AND ps_comment <> 'ial deposits doubt blithely ironic, regular deposits. quickly regular theodolites sleep slyly regular deposits. special requests boost slyly blithely even deposits. carefully special r' AND ps_suppkey <= 602 GROUP BY s_nationkey, ps_comment
select  o_year,  sum(case   when nation = 'IRAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE BURNISHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select l_shipdate, l_suppkey, l_commitdate from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'COLLECT COD'
select p_container, ps_availqty, min(ps_partkey) from part JOIN partsupp ON ps_partkey = p_partkey where p_mfgr = 'Manufacturer#4' AND p_mfgr = 'Manufacturer#1' AND ps_availqty <= 8724 group by p_container, ps_availqty having min(ps_partkey) = 196386
SELECT ps_supplycost, p_size FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE ps_partkey < 127208 AND p_type >= 'LARGE POLISHED NICKEL' AND ps_comment > 'escapades: blithely regular packages ought to cajole blithely even pinto beans. blit' AND p_partkey < 145521
SELECT o_orderdate, l_receiptdate, c_name FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE l_linestatus = 'O' AND l_shipmode <> 'MAIL' AND o_comment >= 'beans. fluffily final theo' AND o_orderstatus > 'P' ORDER BY l_receiptdate DESC, o_orderdate DESC, c_name DESC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 29 and l_quantity <= 29 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT ps_comment, l_extendedprice FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_extendedprice > 4460.36 AND l_quantity = 48.0 AND l_returnflag <= 'R' AND ps_suppkey <> 249 AND ps_comment >= 'urts. fluffily ironic packages are after the furiously final accounts. ruthlessly bold theodolites cajole carefully. re' AND l_receiptdate = '1998-06-30' ORDER BY ps_comment DESC, l_extendedprice ASC
select p_mfgr, ps_availqty, min(ps_partkey) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 5830 AND p_container = 'JUMBO DRUM' AND p_mfgr <= 'Manufacturer#1' group by ps_availqty, p_mfgr having min(ps_partkey) = 18025
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1997-01-01'  and l_shipdate < date '1997-01-01' + interval '1' year  and l_discount between 0.08 - 0.01 and 0.08 + 0.01  and l_quantity < 25 ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '103' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
SELECT o_orderpriority, c_custkey FROM orders JOIN customer ON c_custkey = o_custkey WHERE c_nationkey < 24 AND c_address <= '9RK,n7wKIAmoolf lvQScgnT,5' AND c_name = 'Customer#000070744' AND o_totalprice >= 65599.68 ORDER BY c_custkey DESC
