SELECT ps_partkey, l_shipmode FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_partkey > 24879 AND l_comment <= '. slyly unusual depe' AND l_shipinstruct > 'DELIVER IN PERSON' AND ps_availqty >= 9312
SELECT l_linenumber, ps_partkey FROM lineitem, partsupp WHERE l_commitdate = '1993-01-21' AND ps_comment < 'boost slyly regular sentiments. fluffily bold dependencies are special requests. sp' AND ps_availqty <= 2643 AND l_linenumber < 6 ORDER BY ps_partkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 3  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT l_shipdate, p_type, ps_supplycost FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE p_size >= 31 AND p_brand >= 'Brand#42' AND p_name = 'saddle firebrick hot almond dim' AND l_receiptdate > '1995-12-01' AND l_orderkey <> 4758179
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#25'  and p_type not like 'SMALL BRUSHED%'  and p_size in (17, 13, 16, 14, 34, 37, 38, 44)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_shipdate, p_partkey, l_extendedprice from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where p_comment = 'lly. quickly express' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1998-10-10' AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by l_shipdate DESC, l_extendedprice ASC
SELECT c_address, o_orderpriority FROM orders, customer WHERE o_custkey = 3787 AND c_mktsegment < 'FURNITURE' AND c_custkey = 149303 AND c_name < 'Customer#000106037' ORDER BY c_address DESC
select  o_year,  sum(case   when nation = 'ARGENTINA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM PLATED STEEL'  ) as all_nations group by  o_year order by  o_year ;
select s_comment, l_shipmode, l_partkey, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '19-702-469-2351' AND s_name < 'Supplier#000001926' AND ps_partkey > 52110 group by s_comment, l_shipmode, l_partkey having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#41'  and p_container = 'JUMBO PKG'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT c_custkey, o_comment FROM orders JOIN customer ON c_custkey = o_custkey WHERE o_shippriority >= 0 AND o_totalprice < 63471.44 AND c_address >= 'h,eVqhY6RNow2tvSW2' AND c_mktsegment <= 'FURNITURE' AND o_clerk = 'Clerk#000000890' AND o_orderstatus < 'P'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#13'  and p_type not like 'STANDARD BRUSHED%'  and p_size in (5, 37, 12, 39, 2, 19, 9, 50)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT s_comment, ps_partkey FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey WHERE ps_suppkey >= 9929 AND s_comment >= 'ronic accounts. accounts wake blithely. slyly final pains about the fluffily even' AND s_phone < '15-923-605-6967' AND s_nationkey > 5 AND s_address <= 'hC5Iv7v9tUzm' ORDER BY s_comment ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#31'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 9 and l_quantity <= 9 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 22 and l_quantity <= 22 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1996-01-01'  and l_shipdate < date '1996-01-01' + interval '1' year  and l_discount between 0.02 - 0.01 and 0.02 + 0.01  and l_quantity < 24 ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#33'  and p_type not like 'ECONOMY ANODIZED%'  and p_size in (25, 5, 23, 10, 50, 16, 30, 6)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1998-10-10' AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_name ASC
SELECT r_comment, o_clerk, c_acctbal, n_regionkey FROM region JOIN nation ON n_regionkey = r_regionkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE c_phone > '13-430-487-4678' AND n_name <= 'ETHIOPIA' AND n_comment < 'ic deposits are blithely about the carefully regular pa'
SELECT p_type, l_commitdate, ps_partkey FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_quantity > 34.0 AND l_shipmode = 'AIR' AND p_size = 2 AND p_brand > 'Brand#23' ORDER BY p_type DESC, l_commitdate ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 31  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  o_year,  sum(case   when nation = 'GERMANY' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM BRUSHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 2  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select l_receiptdate, o_totalprice from orders, lineitem where l_discount <= 0.01 AND o_shippriority >= 0 AND o_custkey > 71746 AND l_tax > 0.02 order by o_totalprice DESC, l_receiptdate ASC
select  o_year,  sum(case   when nation = 'PERU' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD POLISHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#53'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 1 and l_quantity <= 1 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#41'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 23 and l_quantity <= 23 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT s_nationkey, ps_supplycost FROM partsupp, supplier WHERE s_name > 'Supplier#000001640' AND s_suppkey >= 1561 AND ps_comment >= 'sts along the pending pinto beans affix quietly about the fluffily final pinto beans. special, bold requests may sleep slyly special requests. pinto beans sleep. deposits breach. quickly re' AND s_comment <= 'efully. fluffily regular packages affix regular instructions. sly, unusual deposits haggle among' AND ps_supplycost = 739.78 AND s_address < 'c6fBN9a 6EOcB1ZjbImMBAQMwI BKScDNVRP8' AND ps_suppkey >= 5599 AND s_phone > '29-277-611-8007' ORDER BY ps_supplycost ASC, s_nationkey ASC
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_receiptdate = '1998-06-30' AND l_orderkey = 4700103 AND l_commitdate < '1992-09-20' AND l_orderkey = 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_name ASC
select p_retailprice, p_container, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipmode = 'MAIL' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1998-10-10' AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_retailprice ASC
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9048 AND s_comment < 'olites engage express foxes. bold platelets sleep. q' AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#21'  and p_type not like 'STANDARD BURNISHED%'  and p_size in (15, 16, 39, 37, 18, 19, 13, 14)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'ETHIOPIA' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'ETHIOPIA'   ) order by  value desc ;
SELECT l_linenumber, ps_suppkey FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_returnflag <= 'N' AND l_comment = 'ld accounts serve express requests. b' AND ps_partkey > 63218 AND ps_availqty >= 9048
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where c_acctbal < 3068.81 AND o_shippriority = 0 AND o_totalprice = 38731.42 AND c_mktsegment > 'BUILDING' AND c_name < 'Customer#000014747'
SELECT p_brand, ps_availqty FROM part, partsupp WHERE ps_suppkey >= 6579 AND ps_availqty >= 5816 AND p_brand < 'Brand#51' AND p_size <> 36 AND p_name = 'firebrick rosy turquoise blanched smoke' AND ps_comment <> 'luffily. furiously special pinto beans nag furiously? carefully pending requests sleep carefully. ironic accounts h' AND p_container < 'MED BAG' AND p_comment < 'ronic pinto bea'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'PERU' and n2.n_name = 'UNITED KINGDOM')     or (n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'PERU')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 34  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('21', '19', '27', '11', '17', '31', '32')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('21', '19', '27', '11', '17', '31', '32')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and o_orderdate >= date '1996-01-01'  and o_orderdate < date '1996-01-01' + interval '1' year group by  n_name order by  revenue desc ;
select l_linestatus, o_totalprice from lineitem, orders where o_totalprice >= 34145.03 AND l_suppkey = 1197 AND l_partkey = 44003 AND l_extendedprice = 28681.83
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1995-09-01'  and l_shipdate < date '1995-09-01' + interval '1' month ;
SELECT o_orderdate, l_quantity FROM lineitem, orders WHERE l_commitdate <= '1993-08-12' AND o_shippriority = 0 AND o_orderstatus <> 'P' AND o_comment = 'ts hinder carefully even sentiments. slyly even foxes along the furiousl'
select l_tax, l_commitdate from lineitem, partsupp where l_linestatus = 'O' AND l_orderkey < 56675 AND ps_availqty < 4781 AND l_extendedprice = 41364.0
select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1993-09-18' AND l_partkey = 4779 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 47  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%rose%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  o_year,  sum(case   when nation = 'VIETNAM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM POLISHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1993-12-01'  and l_shipdate < date '1993-12-01' + interval '1' month ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-10'  and l_shipdate > date '1995-03-10' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('28', '31', '11', '24', '14', '10', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('28', '31', '11', '24', '14', '10', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select ps_comment, l_returnflag, p_mfgr from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where p_brand > 'Brand#24' AND ps_supplycost > 626.9 AND l_linenumber = 4 AND l_linenumber = 7 order by p_mfgr DESC, l_returnflag ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#32'  and p_type not like 'SMALL ANODIZED%'  and p_size in (18, 44, 19, 25, 29, 3, 22, 33)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1993-04-01'  and l_shipdate < date '1993-04-01' + interval '1' month ;
select o_orderpriority, c_custkey, n_comment from orders, customer, nation where o_totalprice < 242911.86 AND c_acctbal = 1481.44 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select s_comment, s_phone, ps_partkey, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_name = 'Supplier#000006042' AND l_partkey < 152696 AND l_shipmode > 'AIR' group by s_comment, ps_partkey, s_phone having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select ps_comment, l_shipmode, l_partkey from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where ps_comment = 'sts along the pending pinto beans affix quietly about the fluffily final pinto beans. special, bold requests may sleep slyly special requests. pinto beans sleep. deposits breach. quickly re' AND p_comment = 'ronic pinto bea' AND p_retailprice = 1707.61 AND l_shipinstruct <= 'DELIVER IN PERSON'
SELECT c_name, o_shippriority FROM customer JOIN orders ON o_custkey = c_custkey WHERE c_name < 'Customer#000140806' AND c_comment < 'ecial dependencies. thinly quiet pinto beans sleep blith' AND c_custkey < 99098 AND o_orderpriority >= '4-NOT SPECIFIED' AND o_orderstatus < 'P' AND c_acctbal >= 8940.9 AND o_comment > 'ously even theodolites. even p' AND o_orderdate <> '1995-09-02'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#23'  and p_type not like 'PROMO ANODIZED%'  and p_size in (29, 38, 22, 30, 45, 40, 49, 36)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#55'  and p_type not like 'STANDARD ANODIZED%'  and p_size in (8, 34, 26, 4, 30, 5, 23, 44)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%chartreuse%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'JORDAN' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'JORDAN'   ) order by  value desc ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_phone = '15-411-560-1974' AND o_orderdate = '1993-09-18' AND o_custkey < 9136 AND o_orderkey < 2232065
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 4693120 AND l_tax < 0.07 AND l_extendedprice = 39003.27
SELECT o_orderdate, l_commitdate, COUNT(o_shippriority) FROM lineitem JOIN orders ON o_orderkey = l_orderkey WHERE o_custkey = 27481 AND o_orderpriority = '2-HIGH' AND l_partkey <= 169433 GROUP BY o_orderdate, l_commitdate ORDER BY l_commitdate ASC, o_orderdate DESC
SELECT ps_availqty FROM partsupp WHERE ps_availqty > 5156 AND ps_suppkey > 8274 AND ps_comment <> 'e carefully pending foxes sleep furiously among the slyly special requests. blithely final req' AND ps_supplycost <> 693.29 AND ps_partkey < 138335
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 14  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select l_shipmode, ps_availqty, ps_partkey, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by l_shipmode, ps_partkey, ps_availqty having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select s_nationkey, ps_comment from partsupp JOIN supplier ON s_suppkey = ps_suppkey where s_comment < 'final, busy instructions. carefully regular requests about the carefully express packages' AND s_comment < 'ic requests nag. blithely regular ideas try to wake quickly eve' AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice < 110238.65 AND c_acctbal = 8771.87 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select ps_supplycost, n_nationkey, s_address, n_regionkey, count(s_acctbal) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 8448 group by n_regionkey, s_address, n_nationkey, ps_supplycost order by n_nationkey DESC, s_address DESC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'PERU' and n2.n_name = 'VIETNAM')     or (n1.n_name = 'VIETNAM' and n2.n_name = 'PERU')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#34'  and p_type not like 'MEDIUM PLATED%'  and p_size in (14, 15, 50, 49, 41, 26, 23, 8)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select r_name, c_nationkey, n_regionkey, c_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where o_comment = 'e blithely. blithely even packages boost after the quickly pending in' AND o_orderdate < '1995-01-28' AND o_custkey = 57710 order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#35'  and p_container = 'SM PACK'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select l_shipinstruct, p_mfgr, l_extendedprice from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where p_container = 'LG DRUM' AND p_mfgr = 'Manufacturer#5' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 41  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select o_comment, o_orderdate, c_name, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_nationkey = 6 AND n_regionkey < 4 AND o_custkey = 84202 order by o_comment ASC, c_name DESC, r_name ASC
