SELECT c_mktsegment, o_comment, n_nationkey FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE n_regionkey < 1 AND c_address <> ',ndjpIeit3Vbfu,hG,A' AND o_clerk > 'Clerk#000000957' AND o_orderpriority > '1-URGENT' ORDER BY c_mktsegment ASC, o_comment ASC
select s_name, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty <= 5816 AND ps_suppkey < 2099 AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select p_comment, ps_availqty, l_returnflag from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey >= 61689 AND ps_comment = 'against the carefully unusual packages boost about the' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('16', '24', '20', '29', '10', '17', '22')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('16', '24', '20', '29', '10', '17', '22')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'UNITED KINGDOM' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'UNITED KINGDOM'   ) order by  value desc ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%peru%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 158317.97 AND o_custkey > 147643 AND l_tax > 0.02 order by o_totalprice DESC, l_receiptdate ASC
SELECT c_nationkey, l_extendedprice, o_orderstatus FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE c_nationkey <> 13 AND l_discount <> 0.03 AND o_orderdate <> '1992-05-29' AND c_comment = 'ar deposits believe special, express foxes. packages cajole slyly e' ORDER BY l_extendedprice ASC, o_orderstatus DESC
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'MOROCCO' group by  s_name order by  numwait desc,  s_name limit 100;
