SELECT n_regionkey, c_phone, l_shipmode, o_comment FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE l_comment < 'n deposits believe doggedly furiou' AND c_custkey = 140986 AND c_nationkey = 0
select ps_comment, r_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where s_name < 'Supplier#000000217' AND ps_availqty = 2301 AND n_comment = 'y above the carefully unusual theodolites. final dugouts are quickly across the furiously regular d'
select ps_suppkey, r_regionkey, s_comment, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 8448 group by ps_suppkey, s_comment, r_regionkey, n_regionkey order by r_regionkey DESC, ps_suppkey DESC
SELECT ps_supplycost, s_address, l_discount, n_regionkey FROM nation JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE ps_partkey = 3362 AND n_name >= 'KENYA' AND s_phone = '26-482-326-3165' AND l_shipmode = 'FOB' ORDER BY n_regionkey DESC, l_discount ASC, s_address ASC
select l_suppkey, l_quantity from lineitem, partsupp where ps_availqty = 5722 AND l_orderkey < 56675 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#12'  and p_container = 'MED PACK'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT r_comment, s_name, n_regionkey, ps_partkey FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey WHERE r_comment > 'ly final courts cajole furiously final excuse' AND r_name = 'AFRICA' AND s_name < 'Supplier#000001004'
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-28'  and l_shipdate > date '1995-03-28' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select o_orderpriority, o_totalprice from orders, lineitem where o_totalprice <= 266256.07 AND l_tax = 0.04 AND o_custkey > 99901 AND l_receiptdate > '1993-05-19' order by o_totalprice DESC, o_orderpriority ASC
select l_comment, ps_supplycost, l_extendedprice, max(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by ps_supplycost, l_extendedprice, l_comment having sum(ps_partkey) <= 75919 order by sum(ps_partkey) DESC, max(s_name) ASC
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%unusual%accounts%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
SELECT p_type, ps_suppkey, s_suppkey FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN supplier ON s_suppkey = ps_suppkey WHERE ps_suppkey > 2569 AND p_comment <= 'ironic dependenc' AND ps_availqty = 5 AND s_comment > 'ts are carefully blithely' ORDER BY p_type DESC, s_suppkey DESC, ps_suppkey DESC
SELECT l_returnflag, c_name, p_mfgr, o_orderpriority, ps_partkey FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE c_name < 'Customer#000060165' AND p_size >= 37 AND l_extendedprice > 2658.52 AND p_name = 'navajo deep wheat plum honeydew'
select  o_year,  sum(case   when nation = 'RUSSIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY BRUSHED STEEL'  ) as all_nations group by  o_year order by  o_year ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('20', '12', '33', '16', '32', '17', '13')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('20', '12', '33', '16', '32', '17', '13')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('11', '33', '22', '28', '19', '16', '17')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('11', '33', '22', '28', '19', '16', '17')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 18062 AND ps_comment = 'wake carefully silently final packages. carefully even deposits use special, re' AND l_shipmode = 'FOB' AND p_retailprice <= 1790.74
select c_mktsegment, c_name, o_totalprice from orders, customer, nation where o_shippriority < 0 AND c_acctbal = 1481.44 AND o_orderstatus = 'P' AND n_comment > 'eans boost carefully special requests. accounts are. carefull' AND c_nationkey < 4
select ps_supplycost, l_linenumber, l_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where p_mfgr > 'Manufacturer#3' AND p_brand = 'Brand#23' AND ps_supplycost <= 334.23 AND l_linenumber > 7 order by l_linenumber DESC, ps_supplycost ASC
SELECT l_linenumber, s_suppkey, ps_suppkey FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE l_linestatus <> 'O' AND l_receiptdate = '1997-09-05' AND l_shipinstruct >= 'NONE' ORDER BY s_suppkey DESC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#41'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'INDONESIA' and n2.n_name = 'MOZAMBIQUE')     or (n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'INDONESIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#44'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 22 and l_quantity <= 22 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'goldenrod%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'BRAZIL' order by  s_name ;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'NONE' AND s_name = 'Supplier#000000551' AND s_suppkey = 9341 order by ps_partkey DESC, s_name ASC
SELECT ps_partkey, l_shipdate FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE ps_comment <= 'ave to cajole along the regular, ironic theodolites. slyly ironic instructions use. quickly final accounts could wake. quick asymptotes sleep toward the slyly even requests. bl' AND l_shipdate = '1995-05-18' AND l_receiptdate < '1997-02-11' AND l_partkey > 141608
SELECT o_orderstatus, l_partkey FROM lineitem JOIN orders ON o_orderkey = l_orderkey WHERE l_commitdate = '1998-10-10' AND o_orderpriority < '3-MEDIUM' AND o_custkey <> 99011 AND l_extendedprice >= 17058.56 ORDER BY o_orderstatus ASC, l_partkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 43  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '99' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  o_year,  sum(case   when nation = 'UNITED STATES' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'R' AND p_brand > 'Brand#23' AND ps_supplycost = 892.42 AND l_linenumber = 5 order by p_mfgr DESC, l_linenumber ASC
select  o_year,  sum(case   when nation = 'MOROCCO' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#13'  and p_type not like 'ECONOMY ANODIZED%'  and p_size in (14, 7, 8, 41, 27, 20, 37, 36)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '81' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 4463 AND s_comment < 'quests could use furiously across the ironic, even f' AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 111.76 AND ps_supplycost <= 91.11
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand > 'Brand#54' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
select  o_year,  sum(case   when nation = 'SAUDI ARABIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BURNISHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#34'  and p_type not like 'SMALL PLATED%'  and p_size in (41, 50, 12, 3, 43, 27, 38, 14)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select s_suppkey, ps_availqty, n_nationkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where n_regionkey <= 0 AND s_acctbal > 2175.72 AND ps_availqty >= 3514 order by ps_availqty ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#53'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#12'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 22 and l_quantity <= 22 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_comment = 'g pending foxes. ironic accounts cajole furiously slyly even courts. blithely unusual plate' AND o_orderdate = '1993-09-18' AND o_custkey < 9136 AND o_orderkey < 2232065
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and o_orderdate >= date '1996-01-01'  and o_orderdate < date '1996-01-01' + interval '1' year group by  n_name order by  revenue desc ;
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%unusual%packages%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 12  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1993-01-01'  and l_receiptdate < date '1993-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060617' AND o_orderdate < '1992-05-23' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select p_mfgr, ps_availqty, min(p_mfgr) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND ps_partkey = 180166 AND p_container <= 'JUMBO PKG' group by p_mfgr, ps_availqty having min(p_mfgr) = 'Manufacturer#5'
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1993-09-01'  and o_orderdate < date '1993-09-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1996-10-01'  and l_shipdate < date '1996-10-01' + interval '1' month ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'JAPAN' and n2.n_name = 'BRAZIL')     or (n1.n_name = 'BRAZIL' and n2.n_name = 'JAPAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 130086.57 AND o_custkey > 71746 AND l_tax > 0.02 order by o_totalprice DESC, l_receiptdate ASC
select ps_suppkey, s_comment, s_nationkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where ps_suppkey > 6420 AND r_regionkey >= 0 group by ps_suppkey, s_comment, s_nationkey, n_regionkey order by ps_suppkey DESC, s_nationkey DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('10', '16', '26', '18', '28', '33', '34')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('10', '16', '26', '18', '28', '33', '34')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select l_linestatus, o_totalprice from lineitem, orders where o_totalprice >= 68621.84 AND o_orderstatus = 'F' AND l_suppkey = 8624 AND l_extendedprice = 2430.26
select ps_availqty, s_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where ps_comment < 'pinto beans. blithely final accounts wake quickly ironic packages. blithely final ideas sleep carefully against the regular accounts. carefully pending epitaphs above' AND r_name = 'AFRICA' AND n_comment = 'ously. final, express gifts cajole a'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 7  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT ps_suppkey, s_address, r_name, p_comment, n_comment FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey WHERE n_name < 'CANADA' AND s_address >= 'g4DgkJDL9q5Sh3UOOm7cEGVRvLmnH' ORDER BY r_name ASC, n_comment ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#22'  and p_type not like 'MEDIUM PLATED%'  and p_size in (11, 3, 49, 16, 35, 33, 19, 25)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  o_year,  sum(case   when nation = 'UNITED STATES' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL POLISHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('21', '30', '12', '16', '29', '25', '11')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('21', '30', '12', '16', '29', '25', '11')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ETHIOPIA' and n2.n_name = 'INDONESIA')     or (n1.n_name = 'INDONESIA' and n2.n_name = 'ETHIOPIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT c_nationkey, o_orderkey, COUNT(o_shippriority) FROM orders JOIN customer ON c_custkey = o_custkey WHERE o_clerk = 'Clerk#000000977' AND c_custkey >= 4987 AND c_comment <= 'gifts. ironic dependencies cajole alongside of the sly' GROUP BY c_nationkey, o_orderkey ORDER BY COUNT(o_shippriority) DESC
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1997-02-01'  and o_orderdate < date '1997-02-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select  o_year,  sum(case   when nation = 'VIETNAM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO POLISHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select o_totalprice, c_mktsegment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'HOUSEHOLD' AND c_mktsegment = 'BUILDING' AND o_custkey = 117499 AND o_orderkey < 2232065
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'JAPAN' and n2.n_name = 'KENYA')     or (n1.n_name = 'KENYA' and n2.n_name = 'JAPAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9048 AND s_comment < 'y. courts do wake slyly. carefully ironic platelets haggle above the slyly regular the' AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 718.28
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'GERMANY' and n2.n_name = 'INDONESIA')     or (n1.n_name = 'INDONESIA' and n2.n_name = 'GERMANY')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select ps_supplycost, s_acctbal, n_nationkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where s_comment < 'carefully final packages haggle bold deposits. carefully silent war' AND n_comment >= 'hely enticingly express accounts. even, final' AND ps_availqty >= 3514 order by n_nationkey ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('TRUCK', 'FOB')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ETHIOPIA' and n2.n_name = 'INDIA')     or (n1.n_name = 'INDIA' and n2.n_name = 'ETHIOPIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT p_container, s_address, ps_suppkey, n_regionkey, MAX(ps_comment) FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey WHERE p_mfgr < 'Manufacturer#3' AND n_name = 'JORDAN' GROUP BY p_container, s_address, ps_suppkey, n_regionkey ORDER BY MAX(ps_comment) DESC
select c_mktsegment, c_phone, n_regionkey, c_nationkey from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where o_comment = 'fily above the silent, even hockey players. carefully final theodolites engage' AND o_orderdate < '1995-01-28' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, n_regionkey DESC, c_phone ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('23', '13', '24', '34', '11', '14', '16')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('23', '13', '24', '34', '11', '14', '16')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 14  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1993-06-01'  and o_orderdate < date '1993-06-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'EGYPT' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'EGYPT'   ) order by  value desc ;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1994-06-01'  and o_orderdate < date '1994-06-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
SELECT c_mktsegment, o_custkey, SUM(c_acctbal) FROM orders, customer WHERE o_clerk >= 'Clerk#000000934' AND c_mktsegment > 'MACHINERY' AND o_orderdate >= '1993-11-05' AND c_name <= 'Customer#000086870' AND c_comment <= 'tes sleep fluffily. blithely final' GROUP BY c_mktsegment, o_custkey ORDER BY SUM(c_acctbal) DESC
select p_comment, l_linenumber, p_container from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand = 'Brand#23' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_comment DESC, l_linenumber ASC
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '106' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ARGENTINA' and n2.n_name = 'CANADA')     or (n1.n_name = 'CANADA' and n2.n_name = 'ARGENTINA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('26', '11', '29', '19', '33', '13', '30')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('26', '11', '29', '19', '33', '13', '30')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'JAPAN' group by  s_name order by  numwait desc,  s_name limit 100;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 27  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 10  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where s_nationkey >= 5 AND s_comment < 'ic requests nag. blithely regular ideas try to wake quickly eve' AND ps_partkey <= 173618 AND ps_supplycost < 718.28 AND s_acctbal > 1944.08 AND ps_availqty <= 4781
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'AUTOMOBILE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-14'  and l_shipdate > date '1995-03-14' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select s_comment, s_address, l_shipmode, min(l_partkey), sum(l_extendedprice) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_suppkey = 7582 AND s_address < 'rDkBXb01POIKjOwrij62uM8O4' AND l_partkey > 167548 group by s_comment, s_address, l_shipmode having min(l_partkey) <= 120307 order by sum(l_extendedprice) DESC, min(l_partkey) ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 18  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'TAKE BACK RETURN' AND s_name = 'Supplier#000000551' AND s_suppkey = 1933 order by ps_partkey DESC, s_name ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'SHIP')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1993-01-01'  and l_receiptdate < date '1993-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('13', '10', '26', '11', '21', '33', '17')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('13', '10', '26', '11', '21', '33', '17')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select r_comment, s_name, r_name, p_mfgr, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where ps_availqty < 662 AND n_comment = 'ic deposits are blithely about the carefully regular pa' AND ps_comment = 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in'
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '63' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1996-03-01'  and o_orderdate < date '1996-03-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '82' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 1 and l_quantity <= 1 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#13'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 12 and l_quantity <= 12 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#12'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 23 and l_quantity <= 23 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'PERU' and n2.n_name = 'SAUDI ARABIA')     or (n1.n_name = 'SAUDI ARABIA' and n2.n_name = 'PERU')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select ps_suppkey, s_comment, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 7399 group by ps_suppkey, s_comment, r_regionkey, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('MAIL', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'misty%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'ARGENTINA' order by  s_name ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 47  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('12', '17', '11', '14', '30', '13', '16')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('12', '17', '11', '14', '30', '13', '16')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#22'  and p_type not like 'ECONOMY BRUSHED%'  and p_size in (11, 10, 42, 29, 34, 9, 23, 3)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 7  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  o_year,  sum(case   when nation = 'JORDAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE PLATED TIN'  ) as all_nations group by  o_year order by  o_year ;
select l_orderkey, s_acctbal, l_discount from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where ps_comment = 'sts wake. quickly final foxes nag ruthlessly regular deposits. fluffily bold accounts are daringly slyly express requests. regular, ironic ideas poach quickly against the quickly unusual reques' AND s_name = 'Supplier#000000551' AND s_suppkey = 1933 order by s_acctbal DESC, l_discount ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('21', '16', '19', '30', '14', '18', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('21', '16', '19', '30', '14', '18', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  o_year,  sum(case   when nation = 'RUSSIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL POLISHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select r_comment, s_comment, ps_partkey, n_regionkey, count(ps_availqty) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 12 AND ps_suppkey = 8448 group by ps_partkey, s_comment, n_regionkey, r_comment order by ps_partkey DESC, s_comment DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('22', '18', '19', '34', '12', '14', '28')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('22', '18', '19', '34', '12', '14', '28')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  o_year,  sum(case   when nation = 'GERMANY' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD ANODIZED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%magenta%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%frosted%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 56675 AND l_tax < 0.05 AND l_extendedprice = 41364.0
select c_mktsegment, c_comment from customer JOIN orders ON o_custkey = c_custkey where o_custkey < 71746 AND o_orderdate = '1993-09-18' AND o_totalprice < 211151.4 AND o_orderkey < 2232065
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where c_mktsegment < 'MACHINERY' AND o_totalprice = 112609.58 AND c_name = 'Customer#000140806' AND o_shippriority > 0 AND c_acctbal < 477.38
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#15'  and p_type not like 'MEDIUM BRUSHED%'  and p_size in (33, 48, 3, 34, 36, 37, 16, 46)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-03'  and l_shipdate > date '1995-03-03' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
SELECT ps_supplycost, s_comment FROM partsupp, supplier WHERE s_nationkey = 10 AND s_suppkey = 1558 AND ps_supplycost <= 302.56 AND s_phone <= '23-696-420-8788' AND s_name >= 'Supplier#000000908' AND s_acctbal >= 8489.12 ORDER BY s_comment ASC
SELECT c_custkey, r_name, n_comment FROM region, nation, customer WHERE n_comment >= 'ic deposits are blithely about the carefully regular pa' AND r_name = 'ASIA' AND c_name < 'Customer#000019378' AND c_comment >= 'he unusual, special foxes haggle quickly' ORDER BY c_custkey DESC, r_name ASC, n_comment DESC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_linenumber, s_comment, ps_comment FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_linenumber > 7 AND l_suppkey = 3648 AND l_quantity > 36.0 ORDER BY l_linenumber ASC, s_comment ASC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'linen%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'JORDAN' order by  s_name ;
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice < 36447.99 AND n_regionkey = 3 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority = 0
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#25'  and p_type not like 'PROMO POLISHED%'  and p_size in (15, 46, 3, 18, 21, 23, 25, 42)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('22', '34', '10', '17', '20', '15', '16')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('22', '34', '10', '17', '20', '15', '16')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_orderkey, ps_supplycost, o_clerk FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE ps_suppkey = 6409 AND l_quantity = 33.0 AND o_orderpriority <> '3-MEDIUM' ORDER BY ps_supplycost ASC, o_clerk ASC, l_orderkey DESC
select  o_year,  sum(case   when nation = 'BRAZIL' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO ANODIZED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#42'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#31'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 29 and l_quantity <= 29 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'SHIP')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1993-01-01'  and l_receiptdate < date '1993-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_returnflag, ps_supplycost, c_custkey, o_totalprice, SUM(ps_partkey) FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE o_orderstatus < 'F' AND o_totalprice >= 51410.18 GROUP BY l_returnflag, ps_supplycost, c_custkey, o_totalprice HAVING SUM(ps_partkey) <= 101
select c_nationkey, c_acctbal, n_comment from orders, customer, nation where c_name < 'Customer#000053507' AND o_totalprice = 231724.6 AND c_mktsegment = 'FURNITURE' AND o_orderstatus > 'P' AND o_shippriority < 0
select l_comment, s_suppkey, l_shipinstruct from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where ps_partkey = 74866 AND s_name = 'Supplier#000000551' AND s_name = 'Supplier#000008932' order by l_shipinstruct DESC, s_suppkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 46  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT l_quantity, ps_partkey FROM lineitem, partsupp WHERE l_discount > 0.03 AND l_extendedprice = 35817.04 AND l_linenumber < 5 AND l_linestatus = 'O' AND l_comment = 'l packages; theodolites'
select s_comment, s_name, p_mfgr, p_partkey, n_nationkey from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where p_mfgr <= 'Manufacturer#3' AND ps_availqty = 8560 AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon'
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 133685.87 AND o_custkey > 106915 AND l_tax > 0.08 order by o_totalprice DESC, l_receiptdate ASC
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1996-09-01'  and l_shipdate < date '1996-09-01' + interval '1' month ;
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'F' AND p_type = 'SMALL BURNISHED NICKEL' AND l_commitdate = '1998-10-10' AND l_orderkey < 2618950 AND ps_comment > 'detect blithely even theodolites. blithely permanent accounts cajole carefully ironic deposits. ironic, careful instructions are i' order by ps_partkey DESC, p_name ASC
SELECT l_comment, p_partkey, ps_supplycost FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE p_mfgr = 'Manufacturer#4' AND l_shipinstruct <> 'DELIVER IN PERSON' AND l_tax > 0.01 AND ps_partkey = 133788 ORDER BY p_partkey DESC, ps_supplycost ASC
select l_partkey, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1993-09-09' AND l_returnflag = 'N' AND ps_availqty >= 8539 AND l_shipinstruct = 'NONE'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#45'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 26 and l_quantity <= 26 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'MOROCCO' and n2.n_name = 'SAUDI ARABIA')     or (n1.n_name = 'SAUDI ARABIA' and n2.n_name = 'MOROCCO')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1996-05-01'  and l_shipdate < date '1996-05-01' + interval '1' month ;
select s_suppkey, ps_availqty, ps_partkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where ps_supplycost < 91.11 AND n_comment >= 'hely enticingly express accounts. even, final' AND ps_availqty >= 3514 order by ps_availqty ASC
select c_nationkey, o_custkey, o_comment, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060617' AND o_orderdate < '1995-01-28' AND n_regionkey = 1 order by c_nationkey ASC, r_name DESC, o_comment ASC
