select ps_suppkey, r_regionkey, n_regionkey, s_nationkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where ps_suppkey > 2481 AND s_comment >= 'across the regular theodolites. regula' group by ps_suppkey, s_nationkey, r_regionkey, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'IRAQ' and n2.n_name = 'MOROCCO')     or (n1.n_name = 'MOROCCO' and n2.n_name = 'IRAQ')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  o_year,  sum(case   when nation = 'UNITED STATES' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM PLATED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('TRUCK', 'SHIP')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select ps_partkey, s_suppkey, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_phone > '25-809-918-5052' AND ps_suppkey = 8448 group by s_suppkey, ps_partkey, r_regionkey, n_regionkey order by ps_partkey DESC, r_regionkey DESC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select ps_suppkey, r_name, s_address, n_regionkey, count(s_suppkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 8448 group by ps_suppkey, s_address, n_regionkey, r_name order by ps_suppkey DESC, r_name DESC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 30  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#33'  and p_type not like 'MEDIUM BRUSHED%'  and p_size in (38, 20, 25, 50, 9, 23, 29, 14)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('FOB', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_comment, ps_availqty, s_acctbal FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_receiptdate < '1993-08-24' AND l_linestatus <= 'F' AND l_returnflag > 'N' ORDER BY l_comment ASC, s_acctbal ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('24', '33', '12', '10', '34', '15', '17')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('24', '33', '12', '10', '34', '15', '17')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT c_nationkey, o_orderpriority, l_quantity, ps_partkey FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE ps_suppkey <= 5599 AND c_mktsegment > 'BUILDING' AND l_linenumber = 2 AND ps_comment > 'ular requests boost pinto beans. even, regular deposits cajole according to the regular foxes. even deposits according to the bravely daring requests print caref' AND l_extendedprice <= 35621.76 AND o_shippriority = 0
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'BRAZIL' group by  s_name order by  numwait desc,  s_name limit 100;
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000149000' AND o_orderdate < '1997-05-30' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
SELECT n_name, s_phone, ps_availqty FROM nation, supplier, partsupp WHERE ps_comment = 'y unusual foxes maintain slyly against the final, special deposits. furiously special requests nag carefully. furiously e' AND n_nationkey = 3 AND ps_availqty < 1178 ORDER BY n_name ASC, ps_availqty DESC, s_phone DESC
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '83' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 15  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT l_shipdate, p_name, ps_comment, MAX(l_commitdate), AVG(l_discount) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_suppkey = 9846 AND p_comment <= 'haggle' AND l_orderkey <= 991332 GROUP BY l_shipdate, p_name, ps_comment
SELECT ps_availqty, s_name FROM partsupp, supplier WHERE s_comment = 'w dolphins. carefully final instructions use silently bold pinto beans. fur' AND s_phone > '31-367-113-9243' AND s_suppkey >= 9076 AND s_acctbal > 7148.52 ORDER BY s_name ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 46  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT o_totalprice, c_custkey FROM orders, customer WHERE o_clerk < 'Clerk#000000623' AND c_phone < '29-192-497-2443' AND o_orderdate = '1996-06-19' AND c_comment < 'ing requests according to the stealthily express requests use among the furiously' AND c_custkey <> 149303
SELECT o_totalprice, l_discount FROM orders, lineitem WHERE l_partkey <= 166867 AND l_linestatus = 'O' AND l_shipmode < 'AIR' AND o_comment <> 'kages. blithely bold platelets play fluffily pending frets. slyly final ins' AND l_comment <> 'bold asymptotes are furiously a'
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1994-01-01'  and l_shipdate < date '1994-01-01' + interval '1' year  and l_discount between 0.09 - 0.01 and 0.09 + 0.01  and l_quantity < 24 ;
SELECT o_shippriority, l_shipmode, MAX(o_clerk) FROM lineitem JOIN orders ON o_orderkey = l_orderkey WHERE o_orderkey <= 3753606 AND l_receiptdate >= '1997-01-30' AND l_shipinstruct <= 'TAKE BACK RETURN' AND o_orderdate < '1994-04-04' AND o_orderstatus > 'O' AND l_comment <= 'furiously even ideas sleep blithely.' GROUP BY o_shippriority, l_shipmode ORDER BY MAX(o_clerk) DESC
select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_partkey = 141608 AND l_returnflag >= 'R' AND l_shipinstruct = 'TAKE BACK RETURN'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#33'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1993-01-01'  and l_shipdate < date '1993-01-01' + interval '1' year  and l_discount between 0.08 - 0.01 and 0.08 + 0.01  and l_quantity < 25 ;
SELECT p_container, ps_supplycost, COUNT(ps_availqty), SUM(p_partkey) FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE ps_supplycost > 878.35 AND ps_partkey < 57203 AND p_brand < 'Brand#35' GROUP BY p_container, ps_supplycost HAVING SUM(p_partkey) <> 55 ORDER BY SUM(p_partkey) DESC, COUNT(ps_availqty) DESC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-21'  and l_shipdate > date '1995-03-21' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  o_year,  sum(case   when nation = 'VIETNAM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE PLATED TIN'  ) as all_nations group by  o_year order by  o_year ;
SELECT o_orderkey, l_linestatus, ps_comment, p_type, SUM(ps_suppkey) FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE o_totalprice >= 37462.59 AND o_orderstatus > 'P' GROUP BY o_orderkey, l_linestatus, ps_comment, p_type ORDER BY SUM(ps_suppkey) DESC
SELECT o_totalprice, l_shipmode, COUNT(o_totalprice) FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE l_suppkey <> 3451 AND l_receiptdate = '1995-03-20' AND o_orderpriority <= '1-URGENT' AND l_comment > 'the slyly unusual courts. b' GROUP BY o_totalprice, l_shipmode
select o_totalprice, ps_partkey, l_shipmode from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where p_mfgr = 'Manufacturer#3' AND ps_partkey = 180166 AND ps_availqty <= 2967 group by p_mfgr, ps_availqty having min(p_container) = 'JUMBO CASE'
SELECT o_comment FROM orders WHERE o_orderpriority > '3-MEDIUM' AND o_custkey <> 115963 AND o_orderkey <> 340804 AND o_clerk <= 'Clerk#000000551' AND o_orderstatus = 'P'
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'FOB')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT p_type, ps_comment FROM part, partsupp WHERE ps_partkey < 65143 AND p_container > 'WRAP PACK' AND p_brand <= 'Brand#44' AND p_comment = 'riously bold d' ORDER BY p_type ASC
SELECT o_orderdate FROM orders WHERE o_clerk > 'Clerk#000000786' AND o_custkey < 95197 AND o_orderstatus < 'P' AND o_shippriority > 0 AND o_orderpriority < '1-URGENT'
SELECT o_orderpriority, r_comment, c_phone, n_name FROM region JOIN nation ON n_regionkey = r_regionkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE n_name >= 'INDONESIA' AND c_custkey = 27039 AND n_comment = 'haggle. carefully final deposits detect slyly agai' ORDER BY o_orderpriority ASC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%chiffon%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
SELECT l_commitdate, s_phone, o_custkey, ps_comment, AVG(ps_availqty) FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE ps_suppkey = 8388 AND ps_supplycost <> 892.42 GROUP BY l_commitdate, s_phone, o_custkey, ps_comment HAVING AVG(ps_availqty) > 8076 ORDER BY AVG(ps_availqty) DESC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#13'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#24'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 17 and l_quantity <= 17 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#31'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 23 and l_quantity <= 23 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%pink%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  o_year,  sum(case   when nation = 'MOZAMBIQUE' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL POLISHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
SELECT s_address, l_suppkey, ps_availqty, COUNT(l_tax) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE s_phone = '18-112-483-3374' AND ps_availqty <= 9354 AND l_extendedprice <> 31417.12 GROUP BY s_address, l_suppkey, ps_availqty
SELECT p_container, l_suppkey, ps_suppkey, MIN(ps_availqty) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE ps_availqty < 8724 AND l_tax > 0.08 AND l_returnflag <= 'R' GROUP BY p_container, l_suppkey, ps_suppkey ORDER BY l_suppkey ASC, p_container ASC, ps_suppkey ASC
select ps_availqty, ps_supplycost, ps_suppkey from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_comment < 'al foxes sleep furiously. ironic packages after the blithely unusu' AND l_partkey = 141608 AND o_orderdate = '1993-08-06' AND l_shipinstruct = 'NONE'
select s_suppkey, ps_availqty, n_nationkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where n_regionkey < 0 AND n_comment >= 'refully final requests. regular, ironi' AND ps_availqty >= 3831 order by ps_availqty ASC
select p_mfgr, p_brand, min(p_partkey) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#3' AND p_retailprice <= 1149.12 group by p_mfgr, p_brand having min(p_partkey) = 145521
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'O' AND l_orderkey < 56675 AND l_tax < 0.03 AND l_extendedprice = 50883.12
select  o_year,  sum(case   when nation = 'VIETNAM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE POLISHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select s_comment, n_regionkey, ps_suppkey, r_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 8448 group by ps_suppkey, s_comment, r_regionkey, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
select s_nationkey, s_acctbal from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_partkey >= 139827 AND s_comment < 'ic requests nag. blithely regular ideas try to wake quickly eve' AND ps_partkey <= 173618 AND s_nationkey >= 17 AND s_name > 'Supplier#000003746' AND ps_supplycost <= 91.11
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT p_comment, ps_supplycost FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE ps_partkey <> 80483 AND p_size <> 37 AND ps_availqty <= 2174 AND ps_supplycost < 610.6
select r_name, n_regionkey, o_orderdate, c_nationkey from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060617' AND o_custkey < 86375 AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1997-08-01'  and l_shipdate < date '1997-08-01' + interval '1' month ;
SELECT s_phone, l_shipmode, ps_availqty FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE s_name <> 'Supplier#000004150' AND s_address <= 'NxR4B,oub4GdMpx8lVaR' AND ps_supplycost = 817.43 AND l_shipdate < '1992-07-26'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'BRAZIL' and n2.n_name = 'UNITED KINGDOM')     or (n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'BRAZIL')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT l_quantity, o_orderpriority, ps_supplycost, MIN(l_comment) FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE ps_comment <> 'ide of the even, ironic instructions nag above the bo' AND l_shipdate = '1998-05-28' AND l_shipmode = 'TRUCK' GROUP BY l_quantity, o_orderpriority, ps_supplycost HAVING MIN(l_comment) > 'ideas nag furiously carefully ev'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#55'  and p_type not like 'SMALL ANODIZED%'  and p_size in (18, 47, 29, 41, 21, 9, 49, 12)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_shipinstruct, ps_comment, p_container from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_extendedprice = 35783.64 AND l_shipinstruct = 'TAKE BACK RETURN' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'MACHINERY'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-02'  and l_shipdate > date '1995-03-02' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#35'  and p_container = 'SM PKG'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT c_phone, l_suppkey, o_shippriority, ps_comment FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE l_linestatus <> 'O' AND c_mktsegment = 'AUTOMOBILE' AND c_comment < 'e carefully regular instructions. furiously even packages engage quickly against' ORDER BY l_suppkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 29  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  o_year,  sum(case   when nation = 'JAPAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE ANODIZED COPPER'  ) as all_nations group by  o_year order by  o_year ;
SELECT l_discount, ps_partkey FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_linestatus <= 'O' AND ps_comment = 'ave to cajole along the regular, ironic theodolites. slyly ironic instructions use. quickly final accounts could wake. quick asymptotes sleep toward the slyly even requests. bl' AND l_tax = 0.06 AND l_shipinstruct > 'NONE' AND l_orderkey < 3996642 AND l_receiptdate >= '1997-06-10' ORDER BY l_discount ASC, ps_partkey ASC
SELECT p_partkey, ps_suppkey FROM partsupp, part WHERE p_name <> 'dim orange dodger khaki light' AND p_mfgr > 'Manufacturer#1' AND ps_availqty = 9854 AND ps_partkey < 49795
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#14'  and p_type not like 'ECONOMY PLATED%'  and p_size in (35, 45, 28, 12, 6, 9, 40, 33)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct > 'NONE' AND l_shipmode = 'FOB' AND s_suppkey = 1933 order by ps_partkey DESC, s_name ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 12  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('22', '17', '15', '13', '10', '32', '34')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('22', '17', '15', '13', '10', '32', '34')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'INDIA' and n2.n_name = 'INDONESIA')     or (n1.n_name = 'INDONESIA' and n2.n_name = 'INDIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 8103 AND s_comment < 'thes cajole above the ironic, regular accounts. regular, regular instructions use' AND ps_partkey <= 49795 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
SELECT l_suppkey, ps_suppkey FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE ps_supplycost <= 718.7 AND l_extendedprice <= 78389.95 AND l_returnflag = 'A' AND l_linenumber < 1 ORDER BY l_suppkey DESC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 33  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'EGYPT' and n2.n_name = 'JORDAN')     or (n1.n_name = 'JORDAN' and n2.n_name = 'EGYPT')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#42'  and p_type not like 'SMALL ANODIZED%'  and p_size in (20, 5, 10, 41, 43, 23, 42, 36)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#35'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#42'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 14 and l_quantity <= 14 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#35'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 21 and l_quantity <= 21 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#34'  and p_type not like 'LARGE ANODIZED%'  and p_size in (41, 37, 46, 20, 45, 40, 42, 1)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT ps_suppkey, s_nationkey, n_regionkey FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey WHERE s_acctbal > 824.94 AND ps_supplycost = 456.0 AND s_address < 'oNRhL5p axvIN' ORDER BY n_regionkey DESC, s_nationkey DESC
select  o_year,  sum(case   when nation = 'IRAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM ANODIZED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%drab%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
SELECT o_custkey, c_name FROM customer JOIN orders ON o_custkey = c_custkey WHERE o_clerk = 'Clerk#000000242' AND c_nationkey = 21 AND o_orderpriority <= '2-HIGH' AND c_mktsegment < 'BUILDING'
SELECT o_shippriority, c_nationkey FROM customer, orders WHERE o_orderkey <> 4109316 AND o_totalprice > 44719.4 AND c_name <> 'Customer#000113704' AND o_custkey = 3787
select l_shipinstruct, p_comment, p_retailprice from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 57835 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'SHIP' AND ps_comment <= 'ckages. accounts wake blithely blithely ironic dependencies. slyly final re'
SELECT ps_suppkey, o_custkey, p_name, l_extendedprice, MAX(l_partkey), MAX(ps_availqty) FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE l_discount >= 0.08 AND o_orderkey = 1472992 GROUP BY ps_suppkey, o_custkey, p_name, l_extendedprice ORDER BY ps_suppkey DESC, l_extendedprice DESC
SELECT o_comment, c_address FROM customer, orders WHERE o_orderstatus = 'P' AND o_custkey > 69260 AND c_phone > '15-663-715-9910' AND c_comment = 'lyly blithely express accounts. slyly even platelets alongside of the special'
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('FOB', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
