select  o_year,  sum(case   when nation = 'ALGERIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY ANODIZED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%aquamarine%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1994-03-01'  and o_orderdate < date '1994-03-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
