SELECT o_custkey, c_phone, r_comment, n_name FROM region JOIN nation ON n_regionkey = r_regionkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE n_comment >= 'eas hang ironic, silent packages. slyly regular packages are furiously over the tithes. fluffily bold' AND o_orderpriority <> '1-URGENT' AND o_clerk >= 'Clerk#000000649' AND r_regionkey <> 2 AND r_comment <= 'lar deposits. blithely final packages cajole. regular waters are final requests. regular accounts are according to' ORDER BY c_phone ASC, o_custkey ASC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'magenta%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'MOROCCO' order by  s_name ;
select l_shipinstruct, o_totalprice from orders, lineitem where o_orderpriority = '4-NOT SPECIFIED' AND l_comment = 'usual requests are furious' AND o_custkey > 71746 AND l_tax > 0.02 order by o_totalprice DESC, l_shipinstruct ASC
select ps_suppkey, s_nationkey, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where ps_suppkey > 5063 AND s_comment >= 'ts nag carefully idle dependencies. final foxes nag according to the even, ir' group by ps_suppkey, n_regionkey, r_regionkey, s_nationkey order by ps_suppkey DESC, r_regionkey DESC
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1994-12-01'  and l_shipdate < date '1994-12-01' + interval '1' month ;
