SELECT l_tax, o_orderpriority, ps_comment FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE ps_suppkey >= 9755 AND ps_availqty = 8584 AND o_orderpriority > '1-URGENT' AND l_partkey < 63858 ORDER BY ps_comment ASC
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 5830 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by p_mfgr, ps_availqty having min(p_container) = 'JUMBO CASE'
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'HOUSEHOLD'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-07'  and l_shipdate > date '1995-03-07' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  o_year,  sum(case   when nation = 'CHINA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BRUSHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%lavender%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
SELECT o_orderstatus, l_tax, c_phone, n_nationkey, r_name FROM region JOIN nation ON n_regionkey = r_regionkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE o_orderdate <= '1994-05-25' AND o_shippriority < 0 ORDER BY l_tax ASC, o_orderstatus DESC, c_phone DESC, n_nationkey ASC
select  o_year,  sum(case   when nation = 'UNITED STATES' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM POLISHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#31'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#32'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 21 and l_quantity <= 21 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'SHIP')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_partkey = 144089 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
SELECT l_linestatus, ps_suppkey, s_suppkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE s_name = 'Supplier#000001455' AND ps_suppkey < 6579 AND s_comment >= 'quickly regular pinto beans. fluffily' ORDER BY s_suppkey ASC, ps_suppkey DESC, l_linestatus DESC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1993-01-01'  and l_receiptdate < date '1993-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('FOB', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#35'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#53'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  o_year,  sum(case   when nation = 'FRANCE' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BRUSHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
SELECT l_discount, ps_partkey, o_totalprice, s_address FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE o_custkey <> 4730 AND o_totalprice > 6631.56 AND o_clerk > 'Clerk#000000890' AND l_suppkey = 9875
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'papaya%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'UNITED KINGDOM' order by  s_name ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1992-11-26' AND l_orderkey < 2618950 AND ps_comment > 'ly ironic dolphins use quickly blithely regular pinto beans. packages nag carefully with the furiously regular theodolites? carefully regular inst' order by ps_partkey DESC, p_name ASC
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1994-01-01'  and l_shipdate < date '1994-01-01' + interval '1' year  and l_discount between 0.05 - 0.01 and 0.05 + 0.01  and l_quantity < 24 ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%cornflower%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#52'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 27 and l_quantity <= 27 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'SAUDI ARABIA' and n2.n_name = 'ALGERIA')     or (n1.n_name = 'ALGERIA' and n2.n_name = 'SAUDI ARABIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select p_mfgr, l_returnflag, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_comment = 'across the regular dolphins' AND p_comment = 'regular, regular' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_mfgr DESC, l_returnflag ASC
select c_acctbal, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'MACHINERY' AND o_orderdate = '1992-11-21' AND o_custkey < 9136 AND o_orderkey < 2232065
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#41'  and p_container = 'WRAP BAG'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 49  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'lavender%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'ROMANIA' order by  s_name ;
SELECT l_linenumber, o_orderstatus, ps_suppkey FROM partsupp, lineitem, orders WHERE l_quantity >= 9.0 AND l_shipinstruct < 'COLLECT COD' AND ps_suppkey <= 3273 AND ps_availqty = 1793 ORDER BY o_orderstatus DESC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 32  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('21', '17', '22', '29', '32', '25', '20')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('21', '17', '22', '29', '32', '25', '20')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#31'  and p_container = 'LG CASE'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#32'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 22 and l_quantity <= 22 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT l_orderkey, o_shippriority FROM lineitem, orders WHERE l_linenumber > 6 AND o_orderdate >= '1993-09-13' AND o_orderstatus <> 'F' AND l_tax <> 0.03 AND l_receiptdate = '1993-01-19' AND o_custkey < 19199 ORDER BY l_orderkey ASC, o_shippriority ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'JAPAN' and n2.n_name = 'MOZAMBIQUE')     or (n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'JAPAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#31'  and p_type not like 'ECONOMY ANODIZED%'  and p_size in (7, 26, 42, 9, 39, 30, 48, 22)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select ps_comment, n_comment, s_address, n_nationkey, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AFRICA' AND s_name <= 'Supplier#000005214' AND p_size = 3
SELECT o_orderstatus, n_comment, c_name, MAX(c_custkey) FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE c_nationkey = 2 AND c_name > 'Customer#000086870' AND c_acctbal = 912.55 AND c_mktsegment < 'MACHINERY' GROUP BY o_orderstatus, n_comment, c_name
select l_shipinstruct, l_shipmode, p_retailprice from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND ps_comment = 'luffily. furiously special pinto beans nag furiously? carefully pending requests sleep carefully. ironic accounts h' AND p_comment <= 'ronic pinto bea'
SELECT o_orderpriority, c_comment FROM orders JOIN customer ON c_custkey = o_custkey WHERE o_custkey < 99901 AND o_totalprice < 25079.15 AND o_orderpriority <> '3-MEDIUM' AND c_address >= 'YBEHKrTMyR4CnpCFlg7SoRBji' ORDER BY o_orderpriority DESC
select l_shipmode, ps_partkey, l_linenumber, max(l_quantity), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by l_shipmode, ps_partkey, l_linenumber having sum(ps_partkey) <= 152695 order by sum(ps_partkey) DESC, max(l_quantity) ASC
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#33'  and p_container = 'SM CAN'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT p_retailprice, ps_availqty FROM part, partsupp WHERE p_comment <> 'lly. quickly express' AND p_retailprice >= 1276.29 AND p_name = 'deep cornflower dim yellow lace' AND ps_supplycost <> 114.96
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#53'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 7 and l_quantity <= 7 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 21 and l_quantity <= 21 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT l_comment, o_orderkey, s_acctbal, ps_partkey, COUNT(s_acctbal), MIN(o_orderpriority), COUNT(o_shippriority), COUNT(l_suppkey) FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE s_suppkey <> 989 AND l_extendedprice = 55105.5 GROUP BY l_comment, o_orderkey, s_acctbal, ps_partkey ORDER BY COUNT(s_acctbal) ASC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'pink%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'RUSSIA' order by  s_name ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#14'  and p_type not like 'LARGE PLATED%'  and p_size in (35, 25, 21, 6, 9, 47, 41, 43)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select s_comment, s_phone, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_name = 'Supplier#000008932' AND l_partkey < 76745 AND ps_partkey > 93272 group by s_comment, s_phone, l_shipmode having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('33', '21', '24', '13', '26', '12', '19')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('33', '21', '24', '13', '26', '12', '19')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 133685.87 AND o_custkey > 71746 AND l_tax > 0.03 order by o_totalprice DESC, l_receiptdate ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#44'  and p_type not like 'STANDARD POLISHED%'  and p_size in (38, 16, 13, 39, 49, 47, 19, 37)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'FOB')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_receiptdate, o_orderdate, ps_suppkey, MAX(o_orderstatus) FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_comment > 'lar foxes according to the' AND ps_supplycost = 466.03 AND l_commitdate >= '1995-12-06' GROUP BY l_receiptdate, o_orderdate, ps_suppkey HAVING MAX(o_orderstatus) <= 'F' ORDER BY MAX(o_orderstatus) DESC
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'A' AND p_brand > 'Brand#23' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
